#include <cstdint>
#include <format>
#include <string>
#include <vector>

std::string hexView(std::uint64_t address, const std::vector<std::uint8_t>& bytes, const std::vector<bool>& readable)
{
    std::string out;
    for (std::size_t row{ 0 }; row < bytes.size(); row += 16)
    {
        out += std::format("{:016X}  ", address + row);
        std::string text;
        for (std::size_t i{ 0 }; i < 16; ++i)
        {
            const std::size_t at{ row + i };
            if (at < bytes.size())
            {
                out += readable[at] ? std::format("{:02X} ", bytes[at]) : std::string("?? ");
                const bool printable{ readable[at] && bytes[at] >= 0x20 && bytes[at] <= 0x7E };
                text += printable ? static_cast<char>(bytes[at]) : '.';
            }
            else
            {
                out += "   ";
            }
            if (i == 7) out += ' ';
        }
        out += "  " + text + "\n";
    }
    return out;
}

unitTests:
static std::vector<std::uint8_t> bytesOf(const std::string& s) { return { s.begin(), s.end() }; }
TEST("one full row")
{
    const auto b{ bytesOf(std::string("Rook") + std::string(12, '\0')) };
    CHECK_EQ(hexView(0x1000, b, std::vector<bool>(16, true)), std::string("0000000000001000  52 6F 6F 6B 00 00 00 00  00 00 00 00 00 00 00 00   Rook............\n"));
}
TEST("the example with an unreadable byte")
{
    auto b{ bytesOf(std::string("Rook") + std::string(12, '\0')) };
    b.push_back(0x0E);
    std::vector<bool> r(17, true);
    r[16] = false;
    const std::string expected{
        "0000000000001000  52 6F 6F 6B 00 00 00 00  00 00 00 00 00 00 00 00   Rook............\n"
        "0000000000001010  ??                                                 .\n" };
    CHECK_EQ(hexView(0x1000, b, r), expected);
}
TEST("a short row past the middle") { const auto b{ bytesOf("ABCDEFGHIJ") }; CHECK_EQ(hexView(0x20, b, std::vector<bool>(10, true)), std::string("0000000000000020  41 42 43 44 45 46 47 48  49 4A                     ABCDEFGHIJ\n")); }
TEST("non-printable and high bytes become dots") { const std::vector<std::uint8_t> b{ 0x41, 0x7F, 0xFF, 0x20 }; CHECK_EQ(hexView(0, b, std::vector<bool>(4, true)), std::string("0000000000000000  41 7F FF 20                                        A.. \n")); }
TEST("nothing") { CHECK_EQ(hexView(0x1000, {}, {}), std::string("")); }

